data class FormContext(val screen:String="",val hindi:Boolean=false,val errors:Map<String,String> = emptyMap(),val attempt:Int=0)
val LocalFormContext=staticCompositionLocalOf{FormContext()}
data class Guide(val hint:String,val example:String,val hindi:String,val keyboard:KeyboardType=KeyboardType.Text)
