fun fieldKey(label:String)=when(label){"ईमेल","Email address"->"Email";"शहर","City (optional)","शहर (वैकल्पिक)"->"City";"राज्य"->"State";"मासिक वेतन से (₹)"->"Monthly salary from (₹)";"मासिक वेतन तक (₹)"->"Monthly salary to (₹)";"काम, ज़िम्मेदारियाँ और लाभ"->"Responsibilities & benefits";"Job title or salon","जॉब या सैलून"->"Name / keywords";else->label}
fun fieldRequired(screen:String,key:String)=when(screen){"profile"->key in setOf("Full name","Mobile","City","State","Experience in years");"employer"->key in setOf("Full name","Mobile","City","State","Salon / business name");"post"->key in setOf("City","State","Monthly salary from (₹)","Monthly salary to (₹)","Responsibilities & benefits","Number of vacancies");"auth"->key=="Email";"admin"->true;else->false}
@Composable fun GuidedField(label:String,value:String,onChange:(String)->Unit,multiline:Boolean=false){val ctx=LocalFormContext.current;val key=fieldKey(label);val g=guides[key]?:Guide("Provide ${label.lowercase()} relevant to this request.","","संबंधित विवरण भरें।");val bring=remember{BringIntoViewRequester()};LaunchedEffect(ctx.attempt){if(ctx.errors.keys.firstOrNull()==key)bring.bringIntoView()};if(key=="Availability to join"){var open by remember{mutableStateOf(false)};Column{Text(if(ctx.hindi)"जॉइन करने का समय · वैकल्पिक" else "Availability to join · Optional");Box{OutlinedButton({open=true},modifier=Modifier.fillMaxWidth()){Text(value.ifBlank{"Select when you can join"})};DropdownMenu(open,{open=false}){(listOf("Immediately","15 days","30 days","Negotiable")+value).filter{it.isNotBlank()}.distinct().forEach{choice->DropdownMenuItem(text={Text(choice)},onClick={onChange(choice);open=false})}}};Text(if(ctx.hindi)g.hindi else g.hint,style=MaterialTheme.typography.bodySmall)};return};OutlinedTextField(value,onChange,label={Text(label+if(fieldRequired(ctx.screen,key))if(ctx.hindi)" · ज़रूरी" else " · Required" else if(ctx.hindi)" · वैकल्पिक" else " · Optional")},placeholder={Text(g.example)},supportingText={Text(ctx.errors[key]?:if(ctx.hindi)g.hindi else g.hint)},isError=ctx.errors.containsKey(key),keyboardOptions=KeyboardOptions(keyboardType=g.keyboard),singleLine=!multiline,minLines=if(multiline)3 else 1,modifier=Modifier.fillMaxWidth().bringIntoViewRequester(bring))}
fun jobErrors(d:JobDraft):Map<String,String> = linkedMapOf<String,String>().apply{if(d.primaryCategoryId.isBlank())put("Job Title","Please select the job role you want to hire.");if(d.city.isBlank())put("City","Enter the job city.");if(d.state.isBlank())put("State","Enter the job state.");val min=d.min.toIntOrNull();val max=d.max.toIntOrNull();if(min==null||min<0)put("Monthly salary from (₹)","Enter a non-negative whole minimum salary.");if(max==null||max<0)put("Monthly salary to (₹)","Enter a non-negative whole maximum salary.");else if(min!=null&&max<min)put("Monthly salary to (₹)","Maximum salary must be at least the minimum salary.");if(d.description.isBlank())put("Responsibilities & benefits","Describe the job duties and services required.");if(d.vacancies.toIntOrNull() !in 1..1000)put("Number of vacancies","Use a whole number from 1 to 1000.")}
fun personalErrors(name:String,mobile:String,email:String,city:String,state:String):LinkedHashMap<String,String> = linkedMapOf<String,String>().apply{if(name.isBlank())put("Full name","Enter your full name.");if(!mobile.matches(Regex("\\+?[0-9]{10,15}")))put("Mobile","Enter 10 digits, or include your country code.");if(email.isNotBlank()&&!android.util.Patterns.EMAIL_ADDRESS.matcher(email).matches())put("Email","Enter a valid email address.");if(city.isBlank())put("City","Enter your city.");if(state.isBlank())put("State","Enter your state.")}
fun profileErrors(d:ProfileDraft):Map<String,String> = personalErrors(d.name,d.mobile,d.email,d.city,d.state).apply{if(d.ids.isEmpty())put("Job Profile","Select at least one job profile.");if(d.years.toIntOrNull() !in 0..70)put("Experience in years","Use a whole number from 0 to 70.");if(d.expectedSalary.isNotBlank()&&(d.expectedSalary.toIntOrNull()?:-1)<0)put("Expected salary ₹","Enter a non-negative whole monthly salary.");if(!d.consent)put("Consent","Accept the privacy policy and terms before saving.")}
fun ownerErrors(d:OwnerProfileDraft):Map<String,String> = personalErrors(d.name,d.mobile,d.email,d.city,d.state).apply{if(d.salon.isBlank())put("Salon / business name","Enter the registered salon name.")}
